def customer_totals(text):
    totals = {}
    for line in text.splitlines()[1:]:
        customer, amount = line.split(',')[:2]
        totals[customer] = totals.get(customer, 0) + amount
    return totals

def to_celsius(text):
    value, unit = float(text[:-1]), text[-1]
    return value if unit == 'C' else value - 32

ORDER = ['DEBUG', 'INFO', 'WARN', 'ERROR']

def at_least(lines, level):
    return [l for l in lines if l.split()[0] == level]

import datetime

def parse(text):
    d, m, y = text.split('/')
    return datetime.date(int(y), int(m), int(d))

def merge(entries):
    result = {}
    for sku, qty in entries:
        result[sku] = qty
    return result

